            VMAP_PERF_T0();
            vmap_render_stat_reset();
            vmap_render_draw_tile(&canvas, &tile, base_x, base_y, (float)scale,
                view->scratch, VMAP_SCRATCH_CAP);
            VMAP_PERF_T1(tile);
            VMAP_PERF_N(n_tiles);
            vmap_render_stat_get(&st, &by);
            s_pf_stores += st;
