    if (view->track) {
        if (labels_drawn && canvas.clip_n > 0u) {
            int32_t x1 = label_drawn.x1;
            int32_t y1 = label_drawn.y1;
            int32_t x2 = label_drawn.x2 + 1;
            int32_t y2 = label_drawn.y2 + 1;
