            for (i = 0; i < canvas.clip_n; i++) {
                if (canvas.clip_x1[i] < x1) {
                    x1 = canvas.clip_x1[i];
                }
                if (canvas.clip_y1[i] < y1) {
                    y1 = canvas.clip_y1[i];
                }
                if (canvas.clip_x2[i] > x2) {
                    x2 = canvas.clip_x2[i];
                }
                if (canvas.clip_y2[i] > y2) {
                    y2 = canvas.clip_y2[i];
