    new_w = w + view->margin * 2;
    new_h = h + view->margin * 2;
    new_stride = lv_draw_buf_width_to_stride(new_w, LV_COLOR_FORMAT_RGB565);
    new_rw = w + 2 * view->r_margin;
    new_rh = h + 2 * view->r_margin;
