    old_cbuf_arena = view->cbuf_arena;
    old_rbuf = view->rbuf;

    view->cbuf = new_cbuf;
    view->cbuf_arena = new_cbuf_arena;
    view->w = new_w;
    view->h = new_h;
    view->view_w = w;
    view->view_h = h;
    view->stride = new_stride;

